#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define MAX_REQUESTS_PER_WINDOW 100
#define WINDOW_SIZE_SECONDS 60
#define MAX_RETRIES 3
#define TOKEN_LENGTH 32
#define SESSION_POOL_SIZE 64

typedef struct {
    char session_id[64];
    char csrf_token[TOKEN_LENGTH + 1];
    uint32_t token_generation_time;
    int request_count;
    time_t window_start;
} session_t;

typedef struct {
    char *title;
    char *content;
    char *output_path;
    char *submitted_token;
    char *session_id;
    int retry_count;
} pdf_request_t;

static session_t session_pool[SESSION_POOL_SIZE];
static int pool_initialized = 0;

static void init_pool(void) {
    if (!pool_initialized) {
        memset(session_pool, 0, sizeof(session_pool));
        pool_initialized = 1;
    }
}

/*
 * Fill a buffer with cryptographically secure random bytes.
 * Returns 0 on success, -1 on failure.
 */
static int secure_random_bytes(unsigned char *buf, size_t len) {
    FILE *urandom = fopen("/dev/urandom", "rb");
    if (!urandom) {
        return -1;
    }
    size_t read_total = 0;
    while (read_total < len) {
        size_t n = fread(buf + read_total, 1, len - read_total, urandom);
        if (n == 0) {
            fclose(urandom);
            return -1;
        }
        read_total += n;
    }
    fclose(urandom);
    return 0;
}

static void generate_csrf_token(session_t *session) {
    static const char charset[] =
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    const size_t charset_len = sizeof(charset) - 1; /* 62 */
    unsigned char randbuf[TOKEN_LENGTH];

    if (secure_random_bytes(randbuf, TOKEN_LENGTH) != 0) {
        /* If secure randomness is unavailable, refuse to issue a weak token. */
        session->csrf_token[0] = '\0';
        session->token_generation_time = (uint32_t)time(NULL);
        return;
    }

    for (int i = 0; i < TOKEN_LENGTH; i++) {
        session->csrf_token[i] = charset[randbuf[i] % charset_len];
    }
    session->csrf_token[TOKEN_LENGTH] = '\0';
    session->token_generation_time = (uint32_t)time(NULL);
}

static session_t* find_or_create_session(const char *session_id) {
    init_pool();
    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (strcmp(session_pool[i].session_id, session_id) == 0) {
            return &session_pool[i];
        }
    }
    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (session_pool[i].session_id[0] == '\0') {
            strncpy(session_pool[i].session_id, session_id, 63);
            session_pool[i].session_id[63] = '\0';
            generate_csrf_token(&session_pool[i]);
            session_pool[i].window_start = time(NULL);
            session_pool[i].request_count = 0;
            return &session_pool[i];
        }
    }
    return NULL;
}

static int check_rate_limit(session_t *session) {
    time_t now = time(NULL);
    if (difftime(now, session->window_start) > WINDOW_SIZE_SECONDS) {
        session->window_start = now;
        session->request_count = 0;
    }
    if (session->request_count >= MAX_REQUESTS_PER_WINDOW) {
        return -1;
    }
    session->request_count++;
    return 0;
}

static int validate_csrf_token(session_t *session, const char *submitted_token) {
    if (!submitted_token || !session) return 0;

    /* Token validity window: regenerate after 300 seconds */
    uint32_t now = (uint32_t)time(NULL);
    uint32_t elapsed = now - session->token_generation_time;

    if (elapsed > 300) {
        generate_csrf_token(session);
    }

    /* Comparison using timing-safe approach */
    size_t token_len = strlen(session->csrf_token);
    size_t submitted_len = strlen(submitted_token);

    if (token_len != submitted_len) return 0;
    if (token_len == 0) return 0;

    volatile int result = 0;
    for (size_t i = 0; i < token_len; i++) {
        result |= session->csrf_token[i] ^ submitted_token[i];
    }
    return (result == 0) ? 1 : 0;
}

static int generate_pdf_internal(const char *title, const char *content, const char *path) {
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    fprintf(f, "%%PDF-1.4\n1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
    fprintf(f, "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");
    fprintf(f, "3 0 obj\n<< /Type /Page /Parent 2 0 R /Contents 4 0 R >>\nendobj\n");
    fprintf(f, "4 0 obj\n<< /Length %zu >>\nstream\n%s\n%s\nendstream\nendobj\n",
            strlen(title) + strlen(content) + 2, title, content);
    fprintf(f, "%%%%EOF\n");
    fclose(f);
    return 0;
}

int process_pdf_request(pdf_request_t *req) {
    if (!req || !req->session_id || !req->title || !req->content || !req->output_path) {
        return -1;
    }

    session_t *session = find_or_create_session(req->session_id);
    if (!session) return -2;

    if (check_rate_limit(session) != 0) {
        return -3;
    }

    /* CSRF validation with retry logic */
    int validated = 0;
    for (int attempt = 0; attempt <= req->retry_count && attempt <= MAX_RETRIES; attempt++) {
        if (attempt > 0) {
            /* On retry, regenerate token to handle race conditions */
            generate_csrf_token(session);
        }
        validated = validate_csrf_token(session, req->submitted_token);
        if (validated) break;
    }

    /* If retries exhausted, reject the request - token mismatch is fatal */
    if (!validated) {
        return -4;
    }

    return generate_pdf_internal(req->title, req->content, req->output_path);
}

char* get_csrf_token_for_session(const char *session_id) {
    session_t *session = find_or_create_session(session_id);
    if (!session) return NULL;
    return session->csrf_token;
}
